KustoQueries.KustoQuery:
let _siteName = '<SiteName>';
let _eventTime = datetime('<EventTimeStamp>');
let _trackEventNames = dynamic(['HostConfigRead', 'ScriptStartNotLoadingExtensionBundle', 'ScriptStartUpLoadedExtension']);
FunctionsLogs
| where PreciseTimeStamp between(_eventTime .. _eventTime + 1d)
| where AppName == _siteName
| where EventName in (_trackEventNames)
| project PreciseTimeStamp, HostVersion, EventPrimaryStampName, EventName, Summary
| take 100

let _eventTime = datetime('<EventTimeStamp>');
let _eventPrimaryStampName = "<EventPrimaryStampName>";
let _targetRoles = dynamic(['DataRole', 'FrontEndRole']);
RoleInstanceHeartbeat
| where PreciseTimeStamp between(_eventTime .. _eventTime + 2h)
| where Role in(_targetRoles)
| where EventPrimaryStampName == _eventPrimaryStampName
| distinct RoleInstance, BuildVersion
| order by BuildVersion desc

let _siteName = '<SiteName>';
let _startTime = datetime('<EventTimeStamp>');
let _endTime = _startTime + 1d;
let columnNames = dynamic(['SiteName', 'SKU', 'Triggers', 'VNETName', 'StackId']);
let rowId = AntaresReadOnlyViews
| where PreciseTimeStamp between(_startTime .. _endTime)
| where ColumnValue contains _siteName 
| where SqlCommand == 'SELECT * FROM  [runtime].[view_Sites]'
| take 1
| project RowId;
AntaresReadOnlyViews
| where PreciseTimeStamp between(_startTime .. _endTime)
| where RowId in (rowId) 
| project ColumnName, ColumnValue, EventPrimaryStampName
| where ColumnName in(columnNames)
